    for classe in Classe.objects.exclude(cd_tipo_senha_id=None):
        Regra.objects.get_or_create(
            cd_empresa_id=classe.cd_empresa_id,
            cd_tipo_senha_id=classe.cd_tipo_senha_id,
            cd_classe_senha_id=classe.pk,
            defaults={
                "nr_prioridade": classe.nr_prioridade,
                "nr_idade_minima": classe.nr_idade_minima,
                "nr_idade_maxima": classe.nr_idade_maxima,
                "sn_ativo": classe.sn_ativo,
            },
        )

    Module = apps.get_model("core", "Module")
    Screen = apps.get_model("core", "ScreenDefinition")
