    PapelModulo = apps.get_model("accounts", "PapelModulo")
    PapelTela = apps.get_model("accounts", "PapelTela")
    modulo, _ = Module.objects.get_or_create(
        code="TOTEM_SENHAS",
        defaults={"title": "Totem de Senhas", "active": True},
    )
    telas = [
        ("Configurar senhas", "totem-configurar-senhas", "atendimento:configurar-senhas", "formulario", 10),
        ("Classes", "totem-classes-senha", "atendimento:classes-senha", "formulario", 20),
        ("Protocolos", "totem-protocolos-senha", "atendimento:protocolos-senha", "formulario", 30),
    ]
    for titulo, slug, acesso, tipo, ordem in telas:
        tela, _ = Screen.objects.update_or_create(
            access_key=acesso,
            defaults={
                "module": modulo,
                "title": titulo,
                "slug": slug,
                "screen_type": tipo,
                "parent_label": "Tabelas" if ordem > 10 else "",
                "table_name": "",
                "allow_query": True,
                "allow_insert": True,
                "allow_update": True,
                "allow_delete": ordem > 10,
                "active": True,
                "order": ordem,
            },
        )
        for grupo in Group.objects.filter(name="TI"):
            papel, _ = Papel.objects.get_or_create(grupo=grupo)
            PapelModulo.objects.get_or_create(papel=papel, modulo=modulo)
            PapelTela.objects.get_or_create(papel=papel, tela=tela)


